import{_ as e}from"./chunks/projects.BdG50VF9.js";import{_ as t,c as r,o,a2 as i}from"./chunks/framework.CIiVzG-O.js";const m=JSON.parse('{"title":"提交前看一遍","description":"在專案資料夾裡逐個查看改動檔案，並在 qDiff 裡直接提交。","frontmatter":{"title":"提交前看一遍","description":"在專案資料夾裡逐個查看改動檔案，並在 qDiff 裡直接提交。"},"headers":[],"relativePath":"zh-TW/guide/projects.md","filePath":"zh-TW/guide/projects.md","lastUpdated":1793948370000}'),s={name:"zh-TW/guide/projects.md"};function l(p,a,c,d,h,n){return o(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="提交前看一遍" tabindex="-1">提交前看一遍 <a class="header-anchor" href="#提交前看一遍" aria-label="Permalink to &quot;提交前看一遍&quot;">​</a></h1><p>每次提交前問一句「我到底改了什麼」，都很值得。用 qDiff 打開專案資料夾， 答案已經擺好了。</p><img src="'+e+'" alt="改動檔案列表與右側彩色差異" class="guide-shot"><h2 id="打開專案資料夾" tabindex="-1">打開專案資料夾 <a class="header-anchor" href="#打開專案資料夾" aria-label="Permalink to &quot;打開專案資料夾&quot;">​</a></h2><p>從「檔案 → 開啟」選一個 Git 專案資料夾，或者直接拖進視窗。qDiff 會把你動過的 檔案收成一列。</p><h2 id="先看列表-再看差異" tabindex="-1">先看列表，再看差異 <a class="header-anchor" href="#先看列表-再看差異" aria-label="Permalink to &quot;先看列表，再看差異&quot;">​</a></h2><p>每個檔案都標著它的狀態：新增、修改、刪除。點開一個，右邊就顯示裡面具體改了 什麼，顏色和按詞高亮跟普通檔案比較完全一樣。</p><p>一個一個看過去就好，列表會記住你看到哪裡，改動再多也不容易漏。</p><h2 id="在同一個視窗裡收尾" tabindex="-1">在同一個視窗裡收尾 <a class="header-anchor" href="#在同一個視窗裡收尾" aria-label="Permalink to &quot;在同一個視窗裡收尾&quot;">​</a></h2><p>確認沒問題，直接在這裡提交。更新、推送、還原、解決衝突也都能在比較介面裡完成， 不用再開別的工具，也不需要帳號。</p><div class="tip custom-block"><p class="custom-block-title">不是專案資料夾？</p><p>普通資料夾照樣能當資料夾來比，<a href="./folders.html">比較資料夾</a>在任何目錄都可用。</p></div><p>接下來：<a href="./more.html">圖片、壓縮檔與更多玩法</a>。</p>',12)])])}const u=t(s,[["render",l]]);export{m as __pageData,u as default};
